function collectDirectoryPaths(nodes) {
  const out = new Set();
  const walk = list => {
    for (const n of list) {
      if (n.type === "directory") {
        out.add(n.path);
        if (n.children?.length) walk(n.children);
      }
    }
  };
  walk(nodes);
  return out;
}
